export function decorate(text) { return "[" + text + "]"; }
decorate.label = "shared";
const functions = { decorate };
export function apply(text) { return functions.decorate(text); }
export function same() { return functions.decorate === decorate; }
export function label() { return functions.decorate.label; }
export function mutate() { functions.decorate.label = "changed"; return decorate.label; }
